from typing import TypedDict


class ResearchState(TypedDict, total=False):
    # User's original question
    question: str

    # Plan generated by the planner
    plan: dict

    # Results from the different research agents
    web_results: list[dict]
    academic_results: list[dict]
    news_results: list[dict]

    # Combined evidence
    evidence: list[dict]

    # Final generated report
    report: str

    # Critic's feedback
    critique: dict

    # Number of research iterations
    iteration: int